WALLET='0x1234567890abcdef1234567890abcdef12345678'; OTHER='0x9999999999999999999999999999999999999999'; WRAPPER='0xD4416b13d2b3a9aBae7AcD5D6C2BbDBE25686401'; SEPOLIA='0x0635513f179D50A207757E05759CbD106d7dFcE8'
