def wa(a):return '0x'+'0'*24+a[2:].lower()
def wu(n):return hex(n)[2:].rjust(64,'0')
def mock(mode='direct'):
 d=WALLET if mode=='direct' else (WRAPPER if mode in ('wrapped','expired') else (SEPOLIA if mode=='sepolia' else OTHER)); w=WALLET if mode in ('wrapped','expired','sepolia') else OTHER; exp=1 if mode=='expired' else 4102444800
 return f"""(()=>{{const l={{}},wallet='{WALLET}',ownerWord='{wa(d)}',wrappedWord='{wa(w)}',getData='0x'+wrappedWord.slice(2)+'{wu(0)}'+'{wu(exp)}';window.ethereum={{request:async({{method,params}})=>{{if(method==='eth_requestAccounts'||method==='eth_accounts')return[wallet];if(method==='eth_chainId')return'0x1';if(method==='wallet_switchEthereumChain')return null;if(method==='eth_blockNumber')return'0x1312d00';if(method==='eth_signTypedData_v4')return'0x'+'cd'.repeat(65);if(method==='personal_sign')return'0x'+'ab'.repeat(65);if(method==='eth_call'){{const data=(params?.[0]?.data||'').toLowerCase();if(data.startsWith('0x02571be3'))return ownerWord;if(data.startsWith('0x6352211e'))return wrappedWord;if(data.startsWith('0x0178fe3f'))return getData;return'0x'+'0'.repeat(64)}}throw new Error('Unsupported '+method)}},on:(e,cb)=>{{(l[e]||(l[e]=[])).push(cb)}},emit:(e,...a)=>{{(l[e]||[]).forEach(cb=>cb(...a))}}}}}})();"""
async def ctx(browser,mode='direct',vp=None):
 c=await browser.new_context(viewport=vp or {'width':1600,'height':1000},device_scale_factor=1,accept_downloads=True);await c.add_init_script(POLY);await c.add_init_script(mock(mode));return c
async def load(p):await p.set_content(HTML,wait_until='load')
async def gate(p,label):
 await p.fill('#agiClubLabelInput',label)
 for x in ['#agiClubOwnerConfirm','#agiClubLicenseConfirm','#agiClubBoundaryConfirm','#agiClubLanguageConfirm','#agiClubNoSecretsConfirm']:await p.check(x)
async def unlock(p,label):await gate(p,label);await p.click('#agiClubVerifyBtn');await p.wait_for_function("!document.body.classList.contains('agc-locked')")
